"""
Tests for the app-level ``default_response_model_exclude_none`` argument on
``FastAPI``.

When ``FastAPI(default_response_model_exclude_none=True)`` is set, every
*path operation* registered on the app should drop ``None``-valued fields from
its response by default - without needing the per-route
``response_model_exclude_none=True`` annotation.

A *path operation* that explicitly passes
``response_model_exclude_none=False`` must still override the app-level default
and include ``None`` fields in its response.
"""
from typing import Optional

from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel


class Item(BaseModel):
    name: str
    description: Optional[str] = None
    price: Optional[float] = None


def test_default_response_model_exclude_none_attribute_default_is_false() -> None:
    app = FastAPI()
    assert app.default_response_model_exclude_none is False


def test_default_response_model_exclude_none_attribute_stored() -> None:
    app = FastAPI(default_response_model_exclude_none=True)
    assert app.default_response_model_exclude_none is True


def test_global_true_omits_none_fields() -> None:
    """App-level default of ``True`` should drop ``None`` fields by default."""
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return Item(name="foo", description=None, price=1.5)

    client = TestClient(app)
    response = client.get("/item")
    assert response.status_code == 200, response.text
    payload = response.json()
    assert payload == {"name": "foo", "price": 1.5}
    assert "description" not in payload
    assert "price" not in [k for k, v in payload.items() if v is None]


def test_global_false_includes_none_fields() -> None:
    """App-level default of ``False`` should keep ``None`` fields in the
    response, preserving the historical FastAPI behavior."""
    app = FastAPI()  # default_response_model_exclude_none=False

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return Item(name="foo", description=None, price=None)

    client = TestClient(app)
    response = client.get("/item")
    assert response.status_code == 200, response.text
    payload = response.json()
    assert payload == {"name": "foo", "description": None, "price": None}
    assert "description" in payload
    assert "price" in payload
    assert payload["description"] is None
    assert payload["price"] is None


def test_global_true_with_explicit_false_override() -> None:
    """A route that explicitly sets ``response_model_exclude_none=False``
    should override the app-level default and keep ``None`` fields, while
    other routes on the same app continue to drop them."""
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return Item(name="foo", description=None, price=2.0)

    @app.get(
        "/item/keep-none",
        response_model=Item,
        response_model_exclude_none=False,
    )
    def get_item_keep_none() -> Item:
        return Item(name="foo", description=None, price=2.0)

    client = TestClient(app)

    # Route using the app-level default: ``None`` fields should be dropped.
    default_response = client.get("/item")
    assert default_response.status_code == 200, default_response.text
    default_payload = default_response.json()
    assert default_payload == {"name": "foo", "price": 2.0}
    assert "description" not in default_payload

    # Route that explicitly opts out: ``None`` fields should remain.
    override_response = client.get("/item/keep-none")
    assert override_response.status_code == 200, override_response.text
    override_payload = override_response.json()
    assert override_payload == {
        "name": "foo",
        "description": None,
        "price": 2.0,
    }
    assert "description" in override_payload
    assert override_payload["description"] is None


def test_global_true_also_applies_to_other_decorators() -> None:
    """The app-level default should propagate to every HTTP method decorator
    (not just ``@app.get``), so that ``POST``, ``PUT`` and friends all drop
    ``None`` fields by default when the app is configured with
    ``default_response_model_exclude_none=True``."""
    app = FastAPI(default_response_model_exclude_none=True)

    @app.post("/item", response_model=Item)
    def post_item() -> Item:
        return Item(name="foo", description=None, price=1.0)

    @app.put("/item", response_model=Item)
    def put_item() -> Item:
        return Item(name="foo", description=None, price=1.0)

    client = TestClient(app)
    for method, endpoint in (("POST", "/item"), ("PUT", "/item")):
        response = client.request(method, endpoint)
        assert response.status_code == 200, response.text
        payload = response.json()
        assert payload == {"name": "foo", "price": 1.0}
        assert "description" not in payload

"""
Tests for the app-level ``default_response_model_exclude_none`` argument on
